def fetch_sent_by_receiver(email, status):
    all=[]
    page_index=0
    page_limit=20
    while True:
        page = apis.venmo.show_sent_payment_requests(
            access_token=access_token,
            query=email,
            status=status,
            page_index=page_index,
            page_limit=page_limit
        )
        if not page:
            break
        all.extend(page)
        if len(page) < page_limit:
            break
        page_index += 1
    return all

def has_existing_work_dinner(email, amount):
    for status in ['pending','approved']:
        reqs = fetch_sent_by_receiver(email, status)
        for r in reqs:
            r_desc = r.get('description')
            r_amt = r.get('amount')
            r_recv = r.get('receiver',{}).get('email') if r.get('receiver') else None
            if r_recv == email and r_desc == 'Work Dinner' and float(r_amt) == float(amount):
                return True, {'status':status,'payment_request_id':r['payment_request_id']}
    return False, None

